import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from "react";
import { Link, useLocation } from "wouter";
import { ArrowDownLeft, ArrowUpRight, Check, CircleAlert, Download, Inbox, LockKeyhole, Mail, Plus, Search, ShieldCheck, Sparkles, TrendingUp, WalletCards } from "lucide-react";
import { toast } from "sonner";
import { trpc } from "@/lib/trpc";
import { AppShell, Button, CopyButton, EmptyState, Field, MarketTicker, PageHeader, PublicFooter, PublicHeader, SectionCard, SelectField, StatusBadge, TextAreaField, MetricCard } from "@/components/vaultora";
import { CryptoFlowChat } from "@/components/CryptoFlowChat";

const planFallback = [
  { id: 1, slug: "starter", name: "Starter", roiPercent: "8.00", durationDays: 30, minAmount: "100.00000000", maxAmount: "4999.00000000", enabled: true, sortOrder: 1 },
  { id: 2, slug: "pro", name: "Pro", roiPercent: "18.00", durationDays: 60, minAmount: "5000.00000000", maxAmount: "24999.00000000", enabled: true, sortOrder: 2 },
  { id: 3, slug: "elite", name: "Elite", roiPercent: "35.00", durationDays: 90, minAmount: "25000.00000000", maxAmount: "1000000.00000000", enabled: true, sortOrder: 3 },
];

function money(value: string | number | null | undefined) { const base = Number(value ?? 0); const currency = typeof window !== "undefined" ? window.localStorage.getItem("vaultora-currency") ?? "USD" : "USD"; const rate = typeof window !== "undefined" ? Number((window as any).__vaultoraRates?.[currency] ?? 0) : 0; const displayCurrency = rate > 0 ? currency : "USD"; const displayValue = rate > 0 ? base * rate : base; return new Intl.NumberFormat(undefined, { style: "currency", currency: displayCurrency, minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(displayValue); }
function date(value: string | Date | null | undefined) { return value ? new Date(value).toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" }) : "—"; }
function transactionDisplay(item: { type: string; actorId: number | null; note: string | null }) { const adminCredit = item.type === "credit" && item.actorId !== null; return { type: adminCredit ? "Credit" : item.type, note: adminCredit ? "Credited to your account" : item.note ?? "Ledger entry" }; }
function FormNotice({ error, success }: { error?: string; success?: string }) { if (!error && !success) return null; return <div className={error ? "form-notice error" : "form-notice success"}><CircleAlert size={16}/>{error ?? success}</div>; }

export function PublicLayout({ children }: { children: ReactNode }) { return <div className="public-page"><PublicHeader/>{children}<PublicFooter/></div>; }

function Hero() {
  const ticker = trpc.market.ticker.useQuery(undefined, { refetchInterval: 60_000 });
  return <section className="hero-section"><div className="hero-orbit orbit-a"/><div className="hero-orbit orbit-b"/><div className="hero-grid"><div className="hero-copy"><p className="eyebrow gold-eyebrow"><span className="eyebrow-line"/> Digital wealth, clarified</p><h1>Put your capital <em>to work</em> with a plan you can see.</h1><p className="hero-lede">Vaultora brings structure, visibility, and calm to your crypto growth strategy. Every balance move is recorded. Nothing disappears into the dark.</p><div className="hero-actions"><Link href="/signup" className="button button-gold button-large">Start building <ArrowUpRight size={17}/></Link><Link href="/plans" className="text-link">Explore plans <span>↗</span></Link></div><div className="hero-proof"><span><ShieldCheck size={15}/> Server-verified ledger</span><span><LockKeyhole size={15}/> Secure account access</span></div></div><div className="hero-visual"><div className="vault-card"><div className="vault-card-top"><span className="eyebrow">Vaultora / 01</span><span className="live-chip"><i/> Live</span></div><div className="vault-balance-label">Available balance</div><div className="vault-balance">$24,860<span>.42</span></div><div className="mini-chart"><span/><span/><span/><span/><span/><span/><span/><span/></div><div className="vault-card-bottom"><div><small>30D return</small><strong className="positive">+18.40%</strong></div><div className="card-token">V</div></div></div><div className="float-note note-one"><span className="note-icon green"><TrendingUp size={14}/></span><div><small>Profit recorded</small><strong>+$1,240.00</strong></div></div><div className="float-note note-two"><span className="note-icon gold"><Check size={14}/></span><div><small>Ledger status</small><strong>All clear</strong></div></div></div></div><div className="hero-market"><div className="market-caption"><span className="eyebrow">Market pulse</span><span>Prices refresh every minute</span></div><div className="hero-market-list">{(ticker.data ?? [{ symbol: "BTC", name: "Bitcoin", price: 104820.12, change: 2.84 }, { symbol: "ETH", name: "Ethereum", price: 3842.76, change: 1.42 }, { symbol: "USDT", name: "Tether", price: 1, change: 0.01 }]).map(item => <div key={item.symbol} className="hero-market-item"><span className="coin-token">{item.symbol.slice(0,1)}</span><b>{item.symbol}</b><strong>${item.price.toLocaleString(undefined, { maximumFractionDigits: 2 })}</strong><span className="positive">+{item.change.toFixed(2)}%</span></div>)}</div></div></section>;
}

export function HomePage() {
  const plans = trpc.plans.list.useQuery();
  const items = plans.data?.length ? plans.data : planFallback;
  return <PublicLayout><Hero/><MarketTicker/><section className="section-block section-split"><div className="section-intro"><p className="eyebrow">How it works</p><h2>A calmer way to compound conviction.</h2><p>Vaultora is designed around a simple promise: know what you chose, know where your balance stands, and know why it changed.</p><Link href="/about" className="text-link">Why Vaultora <span>↗</span></Link></div><div className="steps-list"><div className="step-item"><span>01</span><div><h3>Choose a rhythm</h3><p>Pick a plan that matches your horizon and capital comfort.</p></div></div><div className="step-item"><span>02</span><div><h3>Fund with visibility</h3><p>Submit a deposit and follow it from request to approval.</p></div></div><div className="step-item"><span>03</span><div><h3>Track every move</h3><p>See balances, returns, and platform messages from one vault.</p></div></div></div></section><section className="section-block plans-section"><div className="section-heading-row"><div><p className="eyebrow">Curated plans</p><h2>Choose your operating tempo.</h2></div><Link href="/plans" className="text-link">Compare all plans <span>↗</span></Link></div><div className="plan-grid">{items.map((plan, index) => <PlanCard key={plan.slug} plan={plan} featured={index === 1}/>)}</div></section><section className="section-block trust-band"><div className="trust-mark"><Sparkles size={19}/><span>Designed for clarity</span></div><div><h2>A ledger you can read at a glance.</h2><p>Human language, visible statuses, and server-verified actions make the important parts easy to understand.</p></div><Link href="/signup" className="button button-outline">Open your vault <ArrowUpRight size={16}/></Link></section><section className="section-block testimonials"><div className="section-heading-row"><div><p className="eyebrow">From the vault</p><h2>Quiet confidence, not noise.</h2></div></div><div className="quote-grid"><blockquote>“The difference is the visibility. I always know what is pending, what is approved, and what changed.”<cite>— Daniel R., early Vaultora member</cite></blockquote><blockquote>“It feels like a financial instrument, not a casino interface. The detail is exactly where it should be.”<cite>— Amara K., digital asset investor</cite></blockquote><blockquote>“I can see the plan, the duration, and the audit trail before I make a move.”<cite>— Lucas M., long-term builder</cite></blockquote></div></section><FaqSection/></PublicLayout>;
}

function FaqSection() { const faqs = ["How are deposits reviewed?", "Can I withdraw at any time?", "Are plan returns guaranteed?", "How is my account protected?"]; return <section className="section-block faq-section"><div className="section-intro"><p className="eyebrow">FAQ</p><h2>The short version.</h2><p>Still curious? Our team is one message away.</p><Link href="/contact" className="text-link">Ask a question <span>↗</span></Link></div><div className="faq-list">{faqs.map((q, i) => <details key={q} open={i === 0}><summary>{q}<span>+</span></summary><p>{i === 0 ? "Every deposit is submitted with a transaction ID and reviewed by an authorized Vaultora admin before it credits your balance." : i === 1 ? "You can submit a withdrawal request from your dashboard. Requests remain pending until reviewed and are shown with a clear status." : i === 2 ? "Plan terms are platform examples, not a promise of future performance. Digital asset markets are volatile." : "Sessions, roles, and balance changes are checked on the server, and every balance mutation is recorded in the ledger."}</p></details>)}</div></section>; }

function PlanCard({ plan, featured = false }: { plan: any; featured?: boolean }) { return <div className={`plan-card ${featured ? "featured" : ""}`}>{featured && <span className="featured-label">Most selected</span>}<div className="plan-card-head"><span className="plan-index">0{plan.sortOrder}</span><span className="status-badge status-green"><span/>Live</span></div><h3>{plan.name}</h3><p className="plan-summary">A measured lane for {plan.name.toLowerCase()} conviction.</p><div className="plan-roi"><strong>{plan.roiPercent}%</strong><span>target ROI</span></div><div className="plan-details"><span>Duration <b>{plan.durationDays} days</b></span><span>Range <b>{money(plan.minAmount)}–{money(plan.maxAmount)}</b></span></div><Link href="/signup" className="plan-link">Start with {plan.name} <ArrowUpRight size={15}/></Link></div>; }

export function PlansPage() { const plans = trpc.plans.list.useQuery(); const items = plans.data?.length ? plans.data : planFallback; return <PublicLayout><div className="subpage-hero"><p className="eyebrow gold-eyebrow">Investment plans</p><h1>Capital deserves a clear horizon.</h1><p>Three operating tempos. One transparent ledger.</p></div><section className="section-block"><div className="plan-grid plan-grid-large">{items.map((plan, index) => <PlanCard key={plan.slug} plan={plan} featured={index === 1}/>)}</div></section><section className="section-block comparison-band"><div><p className="eyebrow">Read the terms</p><h2>Plan terms stay visible from first click to final status.</h2></div><p>Returns are illustrative platform terms. Crypto markets can move quickly; consider your own risk tolerance and seek independent advice where appropriate.</p></section></PublicLayout>; }
export function AboutPage() { return <PublicLayout><div className="subpage-hero"><p className="eyebrow gold-eyebrow">About Vaultora</p><h1>A digital vault with the lights on.</h1><p>We believe investing tools should explain themselves.</p></div><section className="section-block narrative-grid"><div><p className="eyebrow">Our operating principle</p><h2>Clarity is a product feature.</h2></div><div className="narrative-copy"><p>Vaultora is built for investors who want a clean way to track crypto growth without losing the thread of what happened. The interface is calm by design. The back office is exacting by necessity.</p><p>Every deposit request, investment debit, withdrawal decision, and admin adjustment is represented in the ledger. You should not need to guess where a number came from.</p><div className="principles"><div><strong>01</strong><span>Visible states</span></div><div><strong>02</strong><span>Server-side control</span></div><div><strong>03</strong><span>Audit by default</span></div></div></div></section><section className="section-block quote-band"><p>“Every balance move is recorded. Nothing disappears into the dark.”</p></section></PublicLayout>; }
export function ContactPage() { return <PublicLayout><div className="subpage-hero"><p className="eyebrow gold-eyebrow">Contact</p><h1>Bring us the question behind the question.</h1><p>Our team responds with context, not canned replies.</p></div><section className="section-block contact-layout"><div className="contact-details"><div><p className="eyebrow">Support desk</p><h2>hello@vaultora.example</h2><p className="muted">We aim to reply within one business day.</p></div><div><p className="eyebrow">For account issues</p><p className="muted">Never share your password or verification code by email. We will never ask for it.</p></div></div><ContactForm/></section></PublicLayout>; }
function ContactForm() { const [sent, setSent] = useState(false); const submit = (e: FormEvent) => { e.preventDefault(); setSent(true); }; return <form className="form-card" onSubmit={submit}><Field label="Your name" required/><Field label="Email address" type="email" required/><label className="field"><span>What can we help with?</span><textarea rows={5} required placeholder="Tell us what you are trying to do…"/></label><Button type="submit">{sent ? <><Check size={16}/> Message noted</> : <>Send message <ArrowUpRight size={16}/></>}</Button></form>; }

function AuthLayout({ title, eyebrow, description, children }: { title: string; eyebrow: string; description: string; children: ReactNode }) { return <div className="auth-page"><div className="auth-aside"><LogoPanel/><div className="auth-aside-copy"><p className="eyebrow gold-eyebrow">{eyebrow}</p><h1>{title}</h1><p>{description}</p></div><MarketTicker/></div><div className="auth-main"><div className="auth-mobile-brand"><Link href="/"><span className="brand-icon">V</span> VAULTORA</Link></div>{children}</div></div>; }
function LogoPanel() { return <div className="logo-panel"><Link href="/" className="brand-mark"><span className="brand-icon">V</span><span className="brand-word">VAULTORA</span></Link><span className="logo-rule"/></div>; }

export function SignupPage() { const [, navigate] = useLocation(); const [message, setMessage] = useState(""); const signup = trpc.auth.signup.useMutation({ onSuccess: () => navigate("/login?registered=1"), onError: err => setMessage(err.message) }); const submit = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const data = Object.fromEntries(new FormData(e.currentTarget)); signup.mutate(data as any); }; return <AuthLayout eyebrow="Start with structure" title="Build your vault with intention." description="Create your account, then sign in with your email and password to open your dashboard."><div className="auth-card"><div className="auth-card-head"><div><p className="eyebrow">Create account</p><h2>Your next chapter starts here.</h2></div><LockKeyhole size={20}/></div><form className="auth-form" onSubmit={submit}><div className="form-grid"><Field name="fullName" label="Full name" placeholder="Alex Morgan" required/><Field name="phone" label="Phone" placeholder="+1 555 000 0000" required/></div><div className="form-grid"><Field name="email" label="Email address" type="email" placeholder="you@example.com" required/><Field name="country" label="Country" placeholder="United States" required/></div><Field name="password" label="Password" type="password" placeholder="8+ characters" required/><Field name="confirmPassword" label="Confirm password" type="password" placeholder="Repeat password" required/><FormNotice error={message}/><Button type="submit" disabled={signup.isPending}>{signup.isPending ? "Creating secure account…" : <>Create account <ArrowUpRight size={16}/></>}</Button></form><p className="auth-switch">Already have an account? <Link href="/login">Log in</Link></p></div></AuthLayout>; }

export function VerifyPage() { const [, navigate] = useLocation(); const userId = Number(new URLSearchParams(window.location.search).get("userId") ?? 0); const [code, setCode] = useState(""); const [message, setMessage] = useState(""); const [cooldown, setCooldown] = useState(0); const verify = trpc.auth.verifyEmail.useMutation({ onSuccess: () => navigate("/login?verified=1"), onError: e => setMessage(e.message) }); const resend = trpc.auth.resendVerification.useMutation({ onSuccess: data => { setMessage(data.alreadyVerified ? "This email is already verified. You can log in." : "A fresh code was sent. Check your inbox."); setCooldown(data.cooldownSeconds ?? 60); }, onError: e => setMessage(e.message) }); useEffect(() => { if (!cooldown) return; const timer = window.setInterval(() => setCooldown(value => Math.max(0, value - 1)), 1000); return () => window.clearInterval(timer); }, [cooldown]); return <AuthLayout eyebrow="Secure the perimeter" title="One small step, then you’re in." description="We sent a six-digit code to your inbox. Enter it here to unlock your Vaultora account."><div className="auth-card narrow"><div className="auth-card-head"><div><p className="eyebrow">Verify email</p><h2>Confirm your address.</h2></div><Mail size={20}/></div><div className="verify-code"><input autoFocus value={code} onChange={e => setCode(e.target.value.replace(/\D/g, "").slice(0, 6))} placeholder="000000" inputMode="numeric" aria-label="6 digit verification code"/><span>6 digits</span></div><FormNotice error={message && /(couldn't|could not|invalid|expired|too many|unavailable|wait)/i.test(message) ? message : undefined} success={message && !/(couldn't|could not|invalid|expired|too many|unavailable|wait)/i.test(message) ? message : undefined}/><Button disabled={verify.isPending || code.length !== 6 || !userId} onClick={() => verify.mutate({ userId, code })}>{verify.isPending ? "Checking code…" : <>Verify email <Check size={16}/></>}</Button><button className="text-button" disabled={cooldown > 0 || resend.isPending || !userId} onClick={() => resend.mutate({ userId })}>{cooldown ? `Resend available in ${cooldown}s` : resend.isPending ? "Sending…" : "Resend code"}</button><p className="auth-switch">Already verified? <Link href="/login">Return to login</Link></p></div></AuthLayout>; }

export function LoginPage() { const [, navigate] = useLocation(); const params = new URLSearchParams(window.location.search); const [message, setMessage] = useState(params.get("registered") ? "Account created. Sign in to open your dashboard." : params.get("verified") ? "Email verified. You can log in now." : ""); const login = trpc.auth.login.useMutation({ onSuccess: data => navigate(data.isAdmin ? "/admin" : "/app"), onError: e => setMessage(e.message) }); const submit = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); login.mutate(Object.fromEntries(new FormData(e.currentTarget)) as any); }; return <AuthLayout eyebrow="Welcome back" title="Your numbers, in focus." description="Log in to see your plan, your balance, and every recorded move."><div className="auth-card narrow"><div className="auth-card-head"><div><p className="eyebrow">Log in</p><h2>Enter the vault.</h2></div><ShieldCheck size={20}/></div><form className="auth-form" onSubmit={submit}><Field name="email" label="Email address" type="email" placeholder="you@example.com" required/><Field name="password" label="Password" type="password" placeholder="Your password" required/><div className="form-row-between"><span className="muted small-copy">Protected session · 7 day duration</span><Link href="/forgot-password">Forgot password?</Link></div><FormNotice error={message && !params.get("registered") && !params.get("verified") ? message : undefined} success={message && (params.get("registered") || params.get("verified")) ? message : undefined}/><Button type="submit" disabled={login.isPending}>{login.isPending ? "Opening vault…" : <>Log in <ArrowUpRight size={16}/></>}</Button></form><p className="auth-switch">New to Vaultora? <Link href="/signup">Create an account</Link></p></div></AuthLayout>; }
export function ForgotPasswordPage() { const [message, setMessage] = useState(""); const [error, setError] = useState(""); const forgot = trpc.auth.forgotPassword.useMutation({ onSuccess: data => { setError(""); setMessage(data.message); }, onError: e => { setMessage(""); setError(e.message); } }); return <AuthLayout eyebrow="Reset access" title="A secure reset, without the guesswork." description="Enter your email and we’ll send a single-use reset link if the account exists."><div className="auth-card narrow"><div className="auth-card-head"><div><p className="eyebrow">Forgot password</p><h2>We’ll help you back in.</h2></div><Mail size={20}/></div><form className="auth-form" onSubmit={e => { e.preventDefault(); setMessage(""); setError(""); forgot.mutate(Object.fromEntries(new FormData(e.currentTarget)) as any); }}><Field name="email" label="Email address" type="email" placeholder="you@example.com" required/><FormNotice error={error} success={message}/><Button type="submit" disabled={forgot.isPending}>{forgot.isPending ? "Checking securely…" : <>Send reset link <ArrowUpRight size={16}/></>}</Button></form><p className="auth-switch"><Link href="/login">Back to login</Link></p></div></AuthLayout>; }
export function ResetPasswordPage() { const [, navigate] = useLocation(); const [message, setMessage] = useState(""); const token = new URLSearchParams(window.location.search).get("token") ?? ""; const reset = trpc.auth.resetPassword.useMutation({ onSuccess: () => navigate("/login?reset=1"), onError: e => setMessage(e.message) }); return <AuthLayout eyebrow="New credentials" title="Reset, then return to focus." description="Choose a new password for your secure Vaultora session."><div className="auth-card narrow"><div className="auth-card-head"><div><p className="eyebrow">Reset password</p><h2>Make it strong.</h2></div><LockKeyhole size={20}/></div><form className="auth-form" onSubmit={e => { e.preventDefault(); reset.mutate({ token, ...(Object.fromEntries(new FormData(e.currentTarget)) as any) }); }}><Field name="password" label="New password" type="password" placeholder="8+ characters" required/><Field name="confirmPassword" label="Confirm new password" type="password" placeholder="Repeat password" required/><FormNotice error={message}/><Button type="submit" disabled={reset.isPending}>{reset.isPending ? "Saving…" : <>Save new password <Check size={16}/></>}</Button></form></div></AuthLayout>; }

function Gate({ admin = false, children }: { admin?: boolean; children: ReactNode }) { const [, navigate] = useLocation(); const { data: me, isLoading } = trpc.auth.me.useQuery(); useEffect(() => { if (!isLoading && !me) navigate("/login"); else if (!isLoading && admin && !me?.isAdmin) navigate("/app"); }, [admin, isLoading, me, navigate]); if (isLoading || !me || (admin && !me.isAdmin)) return <div className="loading-screen"><span className="spinner"/> Loading your vault…</div>; return <>{children}</>; }

export function UserPage({ section }: { section: string }) { return <Gate><AppShell>{section === "overview" ? <DashboardPage/> : section === "deposit" ? <DepositPage/> : section === "invest" ? <InvestPage/> : section === "withdraw" ? <WithdrawPage/> : section === "transactions" ? <TransactionsPage/> : section === "inbox" ? <InboxPage/> : <SettingsPage/>}</AppShell></Gate>; }
export function AdminPage({ section }: { section: string }) { return <Gate admin><AppShell>{section === "overview" ? <AdminOverviewPage/> : section === "users" ? <AdminUsersPage/> : section === "deposits" ? <AdminDepositsPage/> : section === "withdrawals" ? <AdminWithdrawalsPage/> : section === "wallets" ? <AdminWalletsPage/> : section === "messages" ? <AdminMessagesPage/> : <AdminActivityPage/>}</AppShell></Gate>; }

function DashboardPage() { const overview = trpc.dashboard.overview.useQuery(); const transactions = trpc.transactions.mine.useQuery(); return <div><PageHeader eyebrow="Personal vault" title={`Good to see you${overview.data ? "." : ""}`} description="A calm view of your active capital and recorded activity." action={<Link href="/app/invest" className="button button-gold">Put capital to work <ArrowUpRight size={16}/></Link>}/><div className="metrics-grid"><MetricCard label="Available balance" value={money(overview.data?.balance)} detail="Ready to allocate" tone="gold"/><MetricCard label="Active investments" value={String(overview.data?.activeInvestments ?? 0)} detail="Plans in motion" icon={Sparkles} tone="blue"/><MetricCard label="Total profit" value={money(overview.data?.totalProfit)} detail="Recorded returns" icon={TrendingUp} tone="green"/><MetricCard label="Pending withdrawals" value={money(overview.data?.pendingWithdrawals)} detail="Awaiting review" icon={ArrowUpRight} tone="muted"/></div><div className="dashboard-grid"><SectionCard title="Capital pulse" description="A simple read on where your account stands."><div className="pulse-visual"><div className="pulse-line"><span/><span/><span/><span/><span/><span/><span/><span/><span/></div><div className="pulse-footer"><span><i className="dot gold"/> Available to invest</span><strong>{money(overview.data?.balance)}</strong></div></div></SectionCard><SectionCard title="Next best move" description="Keep the loop clear."><div className="next-move"><div className="move-icon"><Sparkles size={20}/></div><div><strong>Review your plan</strong><p>Choose a horizon, then track its progress from the investment tab.</p></div><Link href="/app/invest" className="icon-link"><ArrowUpRight size={18}/></Link></div><div className="security-note"><ShieldCheck size={16}/><span>Server-verified account · balance changes are audited</span></div></SectionCard></div><SectionCard title="Crypto Flow Chat" description="Private guidance for your next crypto move."><CryptoFlowChat/></SectionCard><SectionCard title="Recent activity" description="Your latest recorded ledger entries." action={<Link href="/app/transactions" className="text-link">View all <span>↗</span></Link>}>{transactions.data?.length ? <div className="activity-list">{transactions.data.slice(0, 5).map(item => <div className="activity-row" key={item.id}><span className={`activity-icon ${item.direction === "credit" ? "credit" : "debit"}`}>{item.direction === "credit" ? <ArrowDownLeft size={15}/> : <ArrowUpRight size={15}/>}</span><div><strong>{transactionDisplay(item).type}</strong><small>{transactionDisplay(item).note} · {date(item.createdAt)}</small></div><b className={item.direction === "credit" ? "positive" : "negative"}>{item.direction === "credit" ? "+" : "−"}{money(item.amount)}</b></div>)}</div> : <EmptyState title="Your ledger is quiet" description="Approved deposits and investments will appear here."/>}</SectionCard></div>; }

function DepositPage() { const wallets = trpc.deposits.wallets.useQuery(); const mine = trpc.deposits.mine.useQuery(); const [walletId, setWalletId] = useState(0); const [message, setMessage] = useState(""); const create = trpc.deposits.create.useMutation({ onSuccess: () => { setMessage("Deposit request submitted for review."); mine.refetch(); }, onError: e => setMessage(e.message) }); const selected = wallets.data?.find(item => item.id === Number(walletId)); return <div><PageHeader eyebrow="Fund your vault" title="Deposit with a clear trail." description="Choose a verified address, submit your transaction ID, and follow the review status."/><div className="content-grid two-col"><SectionCard title="New deposit" description="Your request will remain pending until reviewed."><form className="stack-form" onSubmit={e => { e.preventDefault(); const data = Object.fromEntries(new FormData(e.currentTarget)); create.mutate({ walletId: Number(walletId), amount: Number(data.amount), transactionId: String(data.transactionId) }); }}><SelectField label="Asset and network" value={walletId} onChange={e => setWalletId(Number(e.target.value))}><option value={0}>Choose an address</option>{wallets.data?.map(item => <option key={item.id} value={item.id}>{item.coin} · {item.network}{item.label ? ` · ${item.label}` : ""}</option>)}</SelectField>{selected && <div className="address-box"><div><small>Send only {selected.coin} on {selected.network}</small><strong>{selected.address}</strong></div><CopyButton value={selected.address}/></div>}<Field label="Amount (USD)" name="amount" type="number" min="1" step="0.01" placeholder="0.00" required/><Field label="Transaction ID / hash" name="transactionId" placeholder="Paste the transaction reference" required/><FormNotice success={message} error={message && !message.includes("submitted") ? message : undefined}/><Button type="submit" disabled={!selected || create.isPending}>{create.isPending ? "Submitting…" : <>Submit deposit request <ArrowUpRight size={16}/></>}</Button></form></SectionCard><SectionCard title="Deposit requests" description="Your recent funding activity.">{mine.data?.length ? <div className="compact-list">{mine.data.slice(0, 6).map(item => <div className="compact-row" key={item.id}><div><strong>{item.coin} · {money(item.amount)}</strong><small>{item.transactionId.slice(0, 20)}… · {date(item.createdAt)}</small></div><StatusBadge value={item.status}/></div>)}</div> : <EmptyState icon={WalletCards} title="No deposits yet" description="Your submitted requests will appear here."/>}</SectionCard></div></div>; }

function InvestPage() { const plans = trpc.plans.list.useQuery(); const investments = trpc.investments.mine.useQuery(); const overview = trpc.dashboard.overview.useQuery(); const [selected, setSelected] = useState<any>(null); const [amount, setAmount] = useState(""); const [message, setMessage] = useState(""); const create = trpc.investments.create.useMutation({ onSuccess: () => { setMessage("Investment created and balance updated."); investments.refetch(); overview.refetch(); setAmount(""); }, onError: e => setMessage(e.message) }); const items = plans.data?.length ? plans.data : planFallback; return <div><PageHeader eyebrow="Build conviction" title="Choose an investment plan." description="Each plan keeps its horizon, target return, and range visible before you commit."/><div className="plan-grid portal-plans">{items.map((plan, index) => <button key={plan.slug} className={`portal-plan ${selected?.id === plan.id ? "selected" : ""}`} onClick={() => setSelected(plan)}><div className="portal-plan-top"><span>0{index + 1}</span><StatusBadge value={plan.name}/></div><h3>{plan.name}</h3><strong>{plan.roiPercent}%</strong><span>target ROI · {plan.durationDays} days</span><small>{money(plan.minAmount)}–{money(plan.maxAmount)}</small></button>)}</div><div className="content-grid two-col"><SectionCard title="Investment review" description={selected ? `You selected ${selected.name}.` : "Select a plan to begin."}><div className="review-summary"><div><span>Available balance</span><strong>{money(overview.data?.balance)}</strong></div><div><span>Projected return</span><strong>{money(Number(amount || 0) * Number(selected?.roiPercent || 0) / 100)}</strong></div></div><Field label="Investment amount (USD)" value={amount} onChange={e => setAmount(e.target.value)} type="number" min={selected?.minAmount ?? 1} max={selected?.maxAmount} step="0.01" placeholder="0.00"/><FormNotice success={message} error={message && !message.includes("created") ? message : undefined}/><Button disabled={!selected || !amount || create.isPending} onClick={() => create.mutate({ planId: selected.id, amount: Number(amount) })}>{create.isPending ? "Confirming…" : <>Confirm investment <Check size={16}/></>}</Button></SectionCard><SectionCard title="Active investments" description="Plans currently in motion.">{investments.data?.length ? <div className="compact-list">{investments.data.map(item => <div className="compact-row" key={item.investment.id}><div><strong>{item.plan.name} · {money(item.investment.principal)}</strong><small>Ends {date(item.investment.endsAt)} · projected {money(item.investment.expectedProfit)}</small></div><StatusBadge value={item.investment.status}/></div>)}</div> : <EmptyState icon={Sparkles} title="No active plans" description="Choose a plan above when you are ready."/>}</SectionCard></div></div>; }

function WithdrawPage() { const mine = trpc.withdrawals.mine.useQuery(); const [method, setMethod] = useState<"crypto" | "bank">("crypto"); const [message, setMessage] = useState(""); const create = trpc.withdrawals.create.useMutation({ onSuccess: () => { setMessage("Withdrawal request submitted for review."); mine.refetch(); }, onError: e => setMessage(e.message) }); return <div><PageHeader eyebrow="Move with intention" title="Request a withdrawal." description="Choose a destination and submit an authorized withdrawal request."/><div className="content-grid two-col"><SectionCard title="New withdrawal" description="Approved requests are recorded in your ledger."><div className="form-row-between withdrawal-method-toggle"><button type="button" className={method === "crypto" ? "small-action gold-action" : "small-action"} onClick={() => setMethod("crypto")}>Crypto Withdrawal</button><button type="button" className={method === "bank" ? "small-action gold-action" : "small-action"} onClick={() => setMethod("bank")}>Bank Withdrawal</button></div><form className="stack-form" onSubmit={e => { e.preventDefault(); const data = Object.fromEntries(new FormData(e.currentTarget)); if (method === "crypto") create.mutate({ method, coin: String(data.coin), network: String(data.network), walletAddress: String(data.walletAddress), amount: Number(data.amount), withdrawalNote: String(data.withdrawalNote || "") }); else create.mutate({ method, accountHolderName: String(data.accountHolderName), bankName: String(data.bankName), accountNumberIban: String(data.accountNumberIban), swiftBic: String(data.swiftBic || ""), bankCountry: String(data.bankCountry), amount: Number(data.amount), withdrawalNote: String(data.withdrawalNote || "") }); }}><input type="hidden" name="method" value={method}/>{method === "crypto" ? <><div className="form-grid"><SelectField label="Asset" name="coin"><option>BTC</option><option>ETH</option><option>USDT</option></SelectField><Field label="Network" name="network" placeholder="Bitcoin / Ethereum / TRC20" required/></div><Field label="Destination wallet address" name="walletAddress" placeholder="Paste a destination address" required/></> : <><Field label="Account holder name" name="accountHolderName" placeholder="Name on the bank account" required/><Field label="Bank name" name="bankName" placeholder="Receiving bank" required/><Field label="Account number / IBAN" name="accountNumberIban" placeholder="Account number or IBAN" required/><div className="form-grid"><Field label="SWIFT/BIC (where applicable)" name="swiftBic" placeholder="Optional"/><Field label="Bank country" name="bankCountry" placeholder="Country" required/></div></>}<Field label="Withdrawal amount (USD)" name="amount" type="number" min="1" step="0.01" placeholder="0.00" required/><Field label="Optional note or reference" name="withdrawalNote" placeholder="Add a reference for the review team"/><FormNotice success={message} error={message && !message.includes("submitted") ? message : undefined}/><Button type="submit" disabled={create.isPending}>{create.isPending ? "Submitting…" : <>Submit withdrawal request <ArrowUpRight size={16}/></>}</Button></form></SectionCard><SectionCard title="Request history" description="Status and review reasons stay visible.">{mine.data?.length ? <div className="compact-list">{mine.data.map(item => <div className="compact-row" key={item.id}><div><strong>{item.method === "bank" ? "Bank Withdrawal" : "Crypto Withdrawal"} · {money(item.amount)}</strong><small>{item.method === "bank" ? `${item.bankName ?? "Bank"} · ${item.bankCountry ?? ""}` : `${item.coin ?? "Crypto"} · ${(item.walletAddress ?? "").slice(0, 18)}…`} · {date(item.createdAt)}</small></div><StatusBadge value={item.status}/></div>)}</div> : <EmptyState icon={ArrowUpRight} title="No withdrawal requests" description="Submitted requests will appear here."/>}</SectionCard></div></div>; }
function TransactionsPage() { const { data, isLoading } = trpc.transactions.mine.useQuery(); return <div><PageHeader eyebrow="Your ledger" title="Every balance move, explained." description="Credit, debit, deposit, investment, profit, and withdrawal entries in one place." action={<Button variant="outline"><Download size={15}/> Export view</Button>}/><SectionCard title="Transaction history" description={isLoading ? "Loading ledger…" : `${data?.length ?? 0} recent entries`}><div className="table-scroll"><table className="data-table"><thead><tr><th>Type</th><th>Note</th><th>Date</th><th>Balance after</th><th className="align-right">Amount</th></tr></thead><tbody>{data?.map(item => <tr key={item.id}><td><StatusBadge value={transactionDisplay(item).type}/></td><td>{transactionDisplay(item).note}</td><td>{date(item.createdAt)}</td><td>{money(item.balanceAfter)}</td><td className={`align-right ${item.direction === "credit" ? "positive" : "negative"}`}>{item.direction === "credit" ? "+" : "−"}{money(item.amount)}</td></tr>)}</tbody></table>{!data?.length && <EmptyState title="No transaction history" description="Your balance activity will appear after your first approved deposit."/>}</div></SectionCard></div>; }

export function InboxPage() { const inbox = trpc.inbox.list.useQuery(); const mark = trpc.inbox.markRead.useMutation({ onSuccess: () => inbox.refetch() }); return <div><PageHeader eyebrow="Platform inbox" title="Notes from your vault." description="Important account and platform events land here, with the same clarity as your ledger."/><div className="inbox-list">{inbox.data?.map(item => <button className={`inbox-card ${!item.readAt ? "unread" : ""}`} key={item.id} onClick={() => !item.readAt && mark.mutate({ id: item.id })}><div className="inbox-card-top"><StatusBadge value={item.category}/><span>{date(item.createdAt)}</span></div><h3>{item.subject}</h3><p>{item.body}</p>{!item.readAt && <span className="unread-copy">Unread · tap to mark read</span>}</button>)}{!inbox.data?.length && <EmptyState icon={Inbox} title="Your inbox is clear" description="Platform notifications and direct messages will appear here."/>}</div></div>; }

function SettingsPage() { const me = trpc.auth.me.useQuery(); const [message, setMessage] = useState(""); const update = trpc.profile.update.useMutation({ onSuccess: () => { setMessage("Profile updated."); me.refetch(); }, onError: e => setMessage(e.message) }); const password = trpc.profile.changePassword.useMutation({ onSuccess: () => setMessage("Password changed.") , onError: e => setMessage(e.message) }); return <div><PageHeader eyebrow="Profile and settings" title="Keep your details current." description="Your personal information and password are managed server-side."/><div className="content-grid two-col"><SectionCard title="Profile details" description="Used for account communication."><form className="stack-form" onSubmit={e => { e.preventDefault(); update.mutate(Object.fromEntries(new FormData(e.currentTarget)) as any); }}><Field label="Full name" name="fullName" defaultValue={me.data?.fullName ?? ""} required/><Field label="Phone" name="phone" defaultValue={me.data?.phone ?? ""} required/><Field label="Country" name="country" defaultValue={me.data?.country ?? ""} required/><Field label="Email address" value={me.data?.email ?? ""} readOnly/><FormNotice success={message}/><Button type="submit">Save profile <Check size={16}/></Button></form></SectionCard><SectionCard title="Change password" description="Use a unique password you do not reuse elsewhere."><form className="stack-form" onSubmit={e => { e.preventDefault(); password.mutate(Object.fromEntries(new FormData(e.currentTarget)) as any); }}><Field label="Current password" name="currentPassword" type="password" required/><Field label="New password" name="password" type="password" required/><Field label="Confirm new password" name="confirmPassword" type="password" required/><Button type="submit" variant="outline">Update password <LockKeyhole size={16}/></Button></form></SectionCard></div></div>; }

function AdminOverviewPage() { const stats = trpc.admin.dashboard.stats.useQuery(); return <div><PageHeader eyebrow="Operations" title="Control center." description="A clear view of users, deposits, withdrawals, and platform balances." action={<Link href="/admin/wallets" className="button button-gold">Manage addresses <ArrowUpRight size={16}/></Link>}/><div className="metrics-grid"><MetricCard label="Total users" value={String(stats.data?.users ?? 0)} detail="Registered accounts" icon={ShieldCheck} tone="blue"/><MetricCard label="Total deposits" value={money(stats.data?.deposits)} detail="Approved deposits" icon={ArrowDownLeft} tone="green"/><MetricCard label="Pending withdrawals" value={money(stats.data?.pendingWithdrawals)} detail="Awaiting review" icon={ArrowUpRight} tone="gold"/><MetricCard label="Total balances" value={money(stats.data?.balances)} detail="Available across users" icon={CircleDollarIcon} tone="muted"/></div><div className="dashboard-grid"><SectionCard title="Review queues" description="The operational work that needs a decision."><div className="admin-shortcuts"><Link href="/admin/deposits"><span className="shortcut-icon green"><ArrowDownLeft size={16}/></span><div><strong>Deposit approvals</strong><small>Review submitted funding requests</small></div><ArrowUpRight size={16}/></Link><Link href="/admin/withdrawals"><span className="shortcut-icon gold"><ArrowUpRight size={16}/></span><div><strong>Withdrawal approvals</strong><small>Approve or reject with a reason</small></div><ArrowUpRight size={16}/></Link><Link href="/admin/wallets"><span className="shortcut-icon blue"><WalletCards size={16}/></span><div><strong>Deposit addresses</strong><small>Add as many as your operations need</small></div><ArrowUpRight size={16}/></Link></div></SectionCard><SectionCard title="Admin standard" description="Keep every action accountable."><div className="security-note large"><ShieldCheck size={18}/><div><strong>Audit trail enabled</strong><span>Balance edits, approvals, role changes, and wallet configuration are logged with actor and metadata.</span></div></div></SectionCard></div></div>; }
function CircleDollarIcon(props: any) { return <WalletCards {...props}/>; }

function AdminUsersPage() { const [search, setSearch] = useState(""); const users = trpc.admin.users.list.useQuery({ search }); const status = trpc.admin.users.setStatus.useMutation({ onSuccess: () => users.refetch() }); const setAdmin = trpc.admin.users.setAdmin.useMutation({ onSuccess: () => users.refetch() }); const softDelete = trpc.admin.users.softDelete.useMutation({ onSuccess: () => users.refetch(), onError: e => toast.error(e.message) }); const adjust = trpc.admin.users.adjustBalance.useMutation({ onSuccess: () => { users.refetch(); toast.success("Balance adjustment recorded"); }, onError: e => toast.error(e.message) }); return <div><PageHeader eyebrow="People and permissions" title="Users." description="Search the roster, manage access, and record balance adjustments with a note."/><div className="toolbar"><div className="search-field"><Search size={17}/><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search name or email"/></div></div><SectionCard title="User roster" description={`${users.data?.length ?? 0} accounts in view`}><div className="table-scroll"><table className="data-table"><thead><tr><th>User</th><th>Access</th><th>Status</th><th>Joined</th><th className="align-right">Actions</th></tr></thead><tbody>{users.data?.map(user => <tr key={user.id}><td><div className="table-person"><span>{user.fullName.slice(0, 1).toUpperCase()}</span><div><strong>{user.fullName}</strong><small>{user.email}</small><small>{user.phone} · {user.country}</small></div></div></td><td>{user.roles.includes("admin") ? <StatusBadge value="Admin"/> : <span className="muted">User</span>}</td><td><StatusBadge value={user.isSuspended ? "Suspended" : "Active"}/></td><td>{date(user.createdAt)}</td><td className="align-right action-buttons"><button className="small-action" onClick={() => status.mutate({ userId: user.id, suspended: !user.isSuspended })}>{user.isSuspended ? "Activate" : "Suspend"}</button><button className="small-action" onClick={() => setAdmin.mutate({ userId: user.id, enabled: !user.roles.includes("admin") })}>{user.roles.includes("admin") ? "Remove admin" : "Make admin"}</button><button className="small-action gold-action" onClick={() => { const value = Number(window.prompt("Credit amount (USD)", "100")); if (value) adjust.mutate({ userId: user.id, direction: "credit", amount: value, note: "Admin balance adjustment" }); }}>Credit</button><button className="small-action" onClick={() => { const value = Number(window.prompt("Debit amount (USD)", "100")); if (value) adjust.mutate({ userId: user.id, direction: "debit", amount: value, note: "Admin balance adjustment" }); }}>Debit</button><button className="small-action" onClick={() => { if (window.confirm("Soft-delete this user and preserve the audit history?")) softDelete.mutate({ userId: user.id }); }}>Delete</button></td></tr>)}</tbody></table>{!users.data?.length && <EmptyState icon={Search} title="No users match" description="Try a different name or email."/>}</div></SectionCard></div>; }

function AdminDepositsPage() { const list = trpc.admin.deposits.list.useQuery(); const review = trpc.admin.deposits.review.useMutation({ onSuccess: () => list.refetch(), onError: e => toast.error(e.message) }); return <div><PageHeader eyebrow="Funding queue" title="Deposit approvals." description="Review transaction references before crediting a user balance."/><SectionCard title="Deposit requests" description="Approved deposits create a credit ledger entry."><div className="table-scroll"><table className="data-table"><thead><tr><th>User</th><th>Asset</th><th>Amount</th><th>Transaction ID</th><th>Status</th><th className="align-right">Decision</th></tr></thead><tbody>{list.data?.map(item => <tr key={item.request.id}><td><strong>{item.user.fullName}</strong><small>{item.user.email}</small></td><td>{item.request.coin}<small>{item.request.network}</small></td><td>{money(item.request.amount)}</td><td className="mono">{item.request.transactionId.slice(0, 18)}…</td><td><StatusBadge value={item.request.status}/></td><td className="align-right action-buttons">{item.request.status === "pending" ? <><button className="small-action gold-action" onClick={() => review.mutate({ id: item.request.id, decision: "approved" })}>Approve</button><button className="small-action" onClick={() => review.mutate({ id: item.request.id, decision: "rejected", reason: "Transaction reference needs clarification" })}>Reject</button></> : <span className="muted">Reviewed</span>}</td></tr>)}</tbody></table>{!list.data?.length && <EmptyState icon={WalletCards} title="No deposit requests" description="The queue is clear."/>}</div></SectionCard></div>; }
function AdminWithdrawalsPage() { const list = trpc.admin.withdrawals.list.useQuery(); const review = trpc.admin.withdrawals.review.useMutation({ onSuccess: () => list.refetch(), onError: e => toast.error(e.message) }); const mask = (value: string | null | undefined) => value ? `••••${value.slice(-4)}` : "—"; return <div><PageHeader eyebrow="Payout queue" title="Withdrawal approvals." description="Approve or reject crypto and bank withdrawals with a reason that stays visible to the user."/><SectionCard title="Withdrawal requests" description="Bank details are masked in the admin list; approval creates the corresponding ledger entry."><div className="table-scroll"><table className="data-table"><thead><tr><th>User</th><th>Method</th><th>Destination / bank</th><th>Amount</th><th>Submitted</th><th>Status</th><th className="align-right">Decision</th></tr></thead><tbody>{list.data?.map(item => <tr key={item.request.id}><td><strong>{item.user.fullName}</strong><small>{item.user.email}</small></td><td>{item.request.method === "bank" ? "Bank Withdrawal" : "Crypto Withdrawal"}</td><td>{item.request.method === "bank" ? <><strong>{item.request.accountHolderName}</strong><small>{item.request.bankName} · {mask(item.request.accountNumberIban)}</small><small>{item.request.bankCountry}{item.request.swiftBic ? ` · ${item.request.swiftBic}` : ""}</small></> : <><span className="mono">{(item.request.walletAddress ?? "").slice(0, 20)}…</span><small>{item.request.coin ?? "Crypto"} · {item.request.network ?? ""}</small></>}</td><td>{money(item.request.amount)}</td><td>{date(item.request.createdAt)}</td><td><StatusBadge value={item.request.status}/></td><td className="align-right action-buttons">{item.request.status === "pending" ? <><button className="small-action gold-action" onClick={() => review.mutate({ id: item.request.id, decision: "approved" })}>Approve</button><button className="small-action" onClick={() => review.mutate({ id: item.request.id, decision: "rejected", reason: "Please confirm your withdrawal details" })}>Reject</button></> : <span className="muted">Reviewed</span>}</td></tr>)}</tbody></table>{!list.data?.length && <EmptyState icon={ArrowUpRight} title="No withdrawal requests" description="The queue is clear."/>}</div></SectionCard></div>; }
function AdminWalletsPage() { const list = trpc.admin.wallets.list.useQuery(); const [editingId, setEditingId] = useState<number | null>(null); const [form, setForm] = useState({ coin: "BTC", network: "Bitcoin", address: "", label: "", enabled: true, sortOrder: 1 }); const resetForm = () => { setEditingId(null); setForm({ coin: "BTC", network: "Bitcoin", address: "", label: "", enabled: true, sortOrder: 1 }); }; const create = trpc.admin.wallets.create.useMutation({ onSuccess: () => { list.refetch(); resetForm(); toast.success("Deposit address added"); }, onError: e => toast.error(e.message) }); const update = trpc.admin.wallets.update.useMutation({ onSuccess: () => { list.refetch(); resetForm(); toast.success("Deposit address updated"); }, onError: e => toast.error(e.message) }); const toggle = trpc.admin.wallets.toggle.useMutation({ onSuccess: () => list.refetch() }); return <div><PageHeader eyebrow="Wallet configuration" title="Deposit addresses." description="Add as many addresses as your operations need. Users see only enabled entries."/><div className="content-grid two-col"><SectionCard title="Add an address" description="Each address is an independent configuration row."><form className="stack-form" onSubmit={e => { e.preventDefault(); if (editingId) update.mutate({ id: editingId, ...form }); else create.mutate(form); }}><div className="form-grid"><SelectField label="Coin" value={form.coin} onChange={e => setForm({ ...form, coin: e.target.value })}><option>BTC</option><option>ETH</option><option>USDT</option><option>USDC</option></SelectField><Field label="Network" value={form.network} onChange={e => setForm({ ...form, network: e.target.value })} required/></div><Field label="Deposit address" value={form.address} onChange={e => setForm({ ...form, address: e.target.value })} placeholder="Paste address" required/><Field label="Label (optional)" value={form.label} onChange={e => setForm({ ...form, label: e.target.value })} placeholder="Primary vault"/><Field label="Display order" type="number" min="0" value={form.sortOrder} onChange={e => setForm({ ...form, sortOrder: Number(e.target.value) })}/><Button type="submit" disabled={create.isPending || update.isPending}><Plus size={16}/> {editingId ? (update.isPending ? "Saving…" : "Save address") : (create.isPending ? "Adding…" : "Add deposit address")}</Button>{editingId && <button type="button" className="text-button" onClick={resetForm}>Cancel edit</button>}</form></SectionCard><SectionCard title="Configured addresses" description={`${list.data?.length ?? 0} address entries · no fixed limit`}><div className="wallet-admin-list">{list.data?.map(wallet => <div className="wallet-admin-row" key={wallet.id}><div className="wallet-admin-icon">{wallet.coin.slice(0, 1)}</div><div className="wallet-admin-copy"><strong>{wallet.coin} · {wallet.network}</strong><small>{wallet.address}</small><span>{wallet.label ?? "Unlabeled"}</span></div><div className="wallet-admin-actions"><StatusBadge value={wallet.enabled ? "Enabled" : "Disabled"}/><button className="small-action" onClick={() => { setEditingId(wallet.id); setForm({ coin: wallet.coin, network: wallet.network, address: wallet.address, label: wallet.label ?? "", enabled: wallet.enabled, sortOrder: wallet.sortOrder }); }}>Edit</button><button className="small-action" onClick={() => toggle.mutate({ id: wallet.id, enabled: !wallet.enabled })}>{wallet.enabled ? "Disable" : "Enable"}</button><CopyButton value={wallet.address}/></div></div>)}{!list.data?.length && <EmptyState icon={WalletCards} title="No addresses configured" description="Add the first address to make deposits available."/>}</div></SectionCard></div></div>; }
function AdminMessagesPage() { const recipients = trpc.admin.email.recipients.useQuery(); const history = trpc.admin.email.history.useQuery(); const [selectedIds, setSelectedIds] = useState<number[]>([]); const [search, setSearch] = useState(""); const [subject, setSubject] = useState(""); const [body, setBody] = useState(""); const [message, setMessage] = useState(""); const [error, setError] = useState(""); const recipientList = recipients.data ?? []; const sendEmail = trpc.admin.email.send.useMutation({ onSuccess: data => { setError(""); setMessage(data.emailConfigured ? `${data.sent} email${data.sent === 1 ? "" : "s"} accepted by the SMTP provider.` : `${data.sent} accepted; ${data.inboxOnly} saved to inbox only because email delivery is not configured.`); history.refetch(); setSubject(""); setBody(""); setSelectedIds([]); }, onError: e => { setMessage(""); setError(e.message); } }); const visible = recipientList.filter(user => `${user.fullName} ${user.email}`.toLowerCase().includes(search.toLowerCase())); const allSelected = Boolean(recipientList.length) && selectedIds.length === recipientList.length; const toggle = (id: number) => setSelectedIds(current => current.includes(id) ? current.filter(value => value !== id) : [...current, id]); const submitEmail = (event: FormEvent) => { event.preventDefault(); setMessage(""); setError(""); if (!selectedIds.length) { setError("Select at least one recipient."); return; } if (selectedIds.length > 1 && !window.confirm(`Send this email to ${selectedIds.length} selected users? This action cannot be undone.`)) return; sendEmail.mutate({ userIds: selectedIds, subject, body }); }; return <div><PageHeader eyebrow="Communication" title="Email management." description="Send a branded email to one user, a selected group, or all active registered users. Delivery is handled server-side and logged."/><div className="content-grid two-col"><SectionCard title="Compose email" description="Messages use the official Vaultora template and verified SMTP sender configured for the project."><form className="message-form" onSubmit={submitEmail}><div className="email-recipient-toolbar"><strong>{selectedIds.length} selected</strong><button type="button" className="small-action gold-action" onClick={() => setSelectedIds(allSelected ? [] : recipientList.map(user => user.id))}>{allSelected ? "Clear all" : "Select all active users"}</button></div><div className="search-field email-recipient-search"><Search size={16}/><input value={search} onChange={event => setSearch(event.target.value)} placeholder="Search recipients by name or email"/></div><div className="recipient-list">{visible.map(user => <label className="recipient-row" key={user.id}><input type="checkbox" checked={selectedIds.includes(user.id)} onChange={() => toggle(user.id)}/><span><strong>{user.fullName}</strong><small>{user.email}</small></span></label>)}{!visible.length && <p className="muted small-copy">No active users match this search.</p>}</div><Field label="Subject" value={subject} onChange={event => setSubject(event.target.value)} placeholder="A message from Vaultora" required/><TextAreaField label="Message body" value={body} onChange={event => setBody(event.target.value)} rows={8} placeholder="Write your message. Paragraph breaks are preserved in the branded email template." required/><details className="email-preview"><summary>Preview branded email</summary><div className="email-preview-card"><div className="email-preview-brand">V <span>VAULTORA</span></div><h3>{subject || "Your email subject"}</h3><p>{body || "Your message preview will appear here."}</p><small>Sent by Vaultora · Never share your password or security codes.</small></div></details><FormNotice success={message} error={error}/><Button type="submit" disabled={sendEmail.isPending || !selectedIds.length}>{sendEmail.isPending ? "Sending securely…" : <><Mail size={16}/> Send email to {selectedIds.length || "recipients"}</>}</Button></form></SectionCard><SectionCard title="Email history" description={`${history.data?.length ?? 0} recent bulk-email delivery attempts`}><div className="table-scroll"><table className="data-table"><thead><tr><th>Recipient</th><th>Subject</th><th>Sent by</th><th>Date</th><th>Status</th></tr></thead><tbody>{history.data?.map(item => <tr key={item.id}><td><strong>{item.recipientUser?.fullName ?? "User"}</strong><small>{item.recipient}</small></td><td>{item.subject}</td><td>{item.adminUser?.fullName ?? `Admin #${item.adminUserId ?? "—"}`}</td><td>{date(item.createdAt)}</td><td><StatusBadge value={item.status === "sent" ? "Accepted" : item.status}/>{item.error && <small className="email-error">{item.error}</small>}</td></tr>)}</tbody></table>{!history.data?.length && <EmptyState icon={Mail} title="No email history" description="Accepted and failed admin email attempts will appear here."/>}</div></SectionCard></div><SectionCard title="Direct inbox message" description="Keep a platform message in a user's inbox even when external email delivery is unavailable."><DirectMessageForm users={recipients.data ?? []}/></SectionCard></div>; }
function DirectMessageForm({ users }: { users: Array<{ id: number; fullName: string; email: string }> }) { const [message, setMessage] = useState(""); const send = trpc.admin.messages.send.useMutation({ onSuccess: data => setMessage(data.emailStatus === "sent" ? "Message saved to inbox and accepted by the SMTP provider." : "Message saved to the user's inbox. External email delivery is not configured yet."), onError: e => setMessage(e.message) }); return <form className="message-form" onSubmit={event => { event.preventDefault(); const data = Object.fromEntries(new FormData(event.currentTarget)); send.mutate({ userId: Number(data.userId), subject: String(data.subject), body: String(data.body) }); }}><div className="form-grid"><SelectField name="userId" label="Recipient"><option value="">Choose a user</option>{users.map(user => <option key={user.id} value={user.id}>{user.fullName} · {user.email}</option>)}</SelectField><Field name="subject" label="Subject" placeholder="Inbox message" required/></div><TextAreaField name="body" label="Message" rows={4} placeholder="Write a concise inbox note…" required/><FormNotice success={message} error={message && !message.includes("saved") ? message : undefined}/><Button type="submit" disabled={send.isPending}><Inbox size={16}/> {send.isPending ? "Saving…" : "Save inbox message"}</Button></form>; }
function AdminActivityPage() { const list = trpc.admin.activity.list.useQuery(); return <div><PageHeader eyebrow="Audit trail" title="Activity log." description="Every admin decision is recorded with actor, target, and timestamp."/><SectionCard title="Recent admin actions" description={`${list.data?.length ?? 0} entries in view`}><div className="activity-list">{list.data?.map(item => <div className="activity-row" key={item.id}><span className="activity-icon gold"><ShieldCheck size={15}/></span><div><strong>{item.action.replaceAll("_", " ")}</strong><small>{item.targetType ?? "system"} {item.targetId ? `#${item.targetId}` : ""} · {date(item.createdAt)}</small></div><span className="mono muted">admin #{item.adminUserId}</span></div>)}</div>{!list.data?.length && <EmptyState icon={ShieldCheck} title="No admin actions yet" description="The audit trail will populate as the control center is used."/>}</SectionCard></div>; }
